<script setup lang="ts">
import { Head, router } from '@inertiajs/vue3';
import { computed, defineComponent, h, ref } from 'vue';
import AppLayout from '../../Layouts/AppLayout.vue';

type Tab = 'settings' | 'display' | 'styles';
type PreviewDevice = 'desktop' | 'mobile';
type Tokens = Record<string, string | number | boolean>;
interface Experiment { name:string; status:'draft'; primary_metric:'revenue'|'conversion_rate'|'average_order_value'; variant_name:string; variant_traffic_percentage:number }
interface Style { layout: 'carousel' | 'grid'; desktop_columns: number; mobile_columns: number; show_image: boolean; show_vendor: boolean; show_price: boolean; show_compare_at_price: boolean; show_add_to_cart: boolean; tokens: Tokens }
interface Component { uuid: string; strategy_uuid: string; strategy_name: string; name: string; placement: string; status: string; enabled: boolean; heading: string; button_label: string; experiment:Experiment|null; style: Style }
interface Product { shopify_product_id: string; title: string; vendor: string | null; image_url: string | null; price: string | null; compare_at_price: string | null; currency: string; variants: Array<{ title: string; price: string; available_for_sale: boolean }> }
const props = defineProps<{ organization:{id:number;name:string}; store:{id:number;name:string;currency:string}; components:Component[]; products:Product[]; permissions:{manage:boolean} }>();
const clone=<T>(value:T):T=>JSON.parse(JSON.stringify(value)) as T;
const activeTab=ref<Tab>('display');
const previewDevice=ref<PreviewDevice>('desktop');
const selectedId=ref(props.components[0]?.uuid ?? '');
const draft=ref<Component|null>(props.components[0] ? clone(props.components[0]) : null);
const experimentOpen=ref(false);
const experimentForm=ref<Experiment>({name:'Widget design test',status:'draft',primary_metric:'revenue',variant_name:'Variant B',variant_traffic_percentage:50});
const saving=ref(false); const message=ref('');
const tabs:[Tab,string][]=[['settings','Settings'],['display','Display'],['styles','Styles']];
const defaults:Tokens={
  widget_border:'none',mobile_padding_y:20,mobile_padding_x:0,desktop_padding_y:20,desktop_padding_x:0,title_padding:20,title_alignment:'left',mobile_layout:'list',desktop_layout:'grid',product_padding:0,content_alignment:'center',unified_alignment:true,content_radius:0,image_source:'product',image_aspect_ratio:'1:1',image_border:'none',image_radius:0,show_product_name:true,show_description:false,show_reviews:false,show_discount_value:true,discount_text:'(Save *|DISCOUNT|*)',comparison_source:'compare_at_price',variant_display:'dynamic',variant_layout:'dropdown',variant_preselection:'smart_match',show_subscription_options:false,allow_quantity:true,selector_radius:4,select_variant_text:'Select',primary_action:'stay',success_message:'Added',button_radius:0,auto_sync_theme:true,background_color:'#FFFFFF',title_color:'#111827',title_color_mobile:'#111827',title_color_desktop:'#111827',product_background_color:'#FFFFFF',product_name_color:'#111827',description_color:'#64748B',price_color:'#111827',compare_at_color:'#94A3B8',discount_color:'#166534',selector_background_color:'#FFFFFF',selector_border_color:'#CBD5E1',selector_text_color:'#111827',button_color:'#111827',button_border_color:'#111827',button_text_color:'#FFFFFF',title_font_size_mobile:16,title_font_size_desktop:16,title_font_weight_mobile:500,title_font_weight_desktop:500,product_font_size:16,product_font_weight:400,button_font_size:14,button_font_weight:400,custom_css:''
};
const tokens=computed(()=>draft.value ? ({...defaults,...draft.value.style.tokens}) : defaults);
function chooseComponent(){draft.value=clone(props.components.find(row=>row.uuid===selectedId.value) ?? props.components[0]);message.value='';}
function token(key:string,value:string|number|boolean){if(!draft.value)return;draft.value.style.tokens={...defaults,...draft.value.style.tokens,[key]:value};}
function save(){if(!draft.value||!props.permissions.manage)return;saving.value=true;message.value='';router.put(`/organizations/${props.organization.id}/stores/${props.store.id}/personalization/editor/${draft.value.uuid}`,{strategy_uuid:draft.value.strategy_uuid,name:draft.value.name,placement:draft.value.placement,heading:draft.value.heading,button_label:draft.value.button_label,experiment:draft.value.experiment,style:draft.value.style,enabled:draft.value.enabled},{preserveScroll:true,onSuccess:()=>{message.value='Widget design saved.';},onError:(errors)=>{message.value=Object.values(errors).join('; ');},onFinish:()=>{saving.value=false;}})}
function resetTheme(){if(!draft.value)return;draft.value.style.tokens={...defaults,auto_sync_theme:true};message.value='Store theme defaults restored. Save to apply.';}
async function copyInstallation(){if(!draft.value)return;const code=`{% render 'deco-personalization', component: '${draft.value.uuid}' %}`;await navigator.clipboard.writeText(code);message.value='Installation code copied.';}
function openExperiment(){if(!draft.value)return;experimentForm.value=clone(draft.value.experiment??{name:`${draft.value.name} A/B test`,status:'draft',primary_metric:'revenue',variant_name:'Variant B',variant_traffic_percentage:50});experimentOpen.value=true;}
function createExperiment(){if(!draft.value)return;draft.value.experiment=clone(experimentForm.value);experimentOpen.value=false;message.value='A/B test draft added. Save the widget to keep it.';}
const previewProducts=computed(()=>props.products.length?props.products:[{shopify_product_id:'1',title:'Recommended product',vendor:'Your store',image_url:null,price:'99.00',compare_at_price:'129.00',currency:props.store.currency,variants:[]}]);
const money=(value:string|null,currency:string)=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(Number(value??0));
const discount=(product:Product)=>{const price=Number(product.price);const compare=Number(product.compare_at_price);return compare>price&&price>=0?`${Math.round((1-price/compare)*100)}%`:null};
const previewStyle=computed(()=>{const mobile=previewDevice.value==='mobile';return {background:String(tokens.value.background_color),padding:`${tokens.value[mobile?'mobile_padding_y':'desktop_padding_y']}px ${tokens.value[mobile?'mobile_padding_x':'desktop_padding_x']}px`,border:tokens.value.widget_border==='solid'?'1px solid #d1d5db':'none',borderRadius:`${tokens.value.content_radius}px`,textAlign:String(tokens.value.content_alignment) as 'left'|'center'|'right'}});
const previewGrid=computed(()=>{const mobile=previewDevice.value==='mobile';return {display:'grid',gridTemplateColumns:`repeat(${mobile?(draft.value?.style.mobile_columns??1):(draft.value?.style.desktop_columns??3)}, minmax(0,1fr))`,gap:'16px'}});
const Section=defineComponent({props:{title:{type:String,required:true}},setup(p,{slots}){return()=>h('section',{class:'section'},[h('h3',p.title),slots.default?.()])}});
const Label=defineComponent({props:{text:{type:String,required:true}},setup(p,{slots}){return()=>h('label',{class:'label'},[h('span',p.text),slots.default?.()])}});
const Check=defineComponent({props:{label:String,checked:Boolean,disabled:Boolean},emits:['update'],setup(p,{emit}){return()=>h('label',{class:['check',p.disabled?'disabled':'']},[h('input',{type:'checkbox',checked:p.checked,disabled:p.disabled,onChange:(e:Event)=>emit('update',(e.target as HTMLInputElement).checked)}),h('span',p.label)])}});
const Radio=defineComponent({props:{label:String,value:String,model:String},emits:['update'],setup(p,{emit}){return()=>h('label',{class:'check'},[h('input',{type:'radio',checked:p.model===p.value,onChange:()=>emit('update',p.value)}),h('span',p.label)])}});
const NumberControl=defineComponent({props:{label:String,value:Number,min:{type:Number,default:0},max:{type:Number,default:48}},emits:['update'],setup(p,{emit}){return()=>h('label',{class:'label'},[h('span',p.label),h('div',{class:'number'},[h('input',{type:'number',value:p.value,min:p.min,max:p.max,onInput:(e:Event)=>emit('update',Number((e.target as HTMLInputElement).value))}),h('em','px')])])}});
const WeightControl=defineComponent({props:{label:String,value:Number},emits:['update'],setup(p,{emit}){return()=>h('label',{class:'label'},[h('span',p.label),h('select',{value:p.value,onChange:(e:Event)=>emit('update',Number((e.target as HTMLSelectElement).value))},[400,500,600,700,800].map(v=>h('option',{value:v},v===400?'Regular':v===500?'Medium':v===700?'Bold':String(v))))])}});
const ColorControl=defineComponent({props:{label:String,value:String},emits:['update'],setup(p,{emit}){return()=>h('label',{class:'color'},[h('span',p.label),h('input',{type:'color',value:p.value,onInput:(e:Event)=>emit('update',(e.target as HTMLInputElement).value.toUpperCase())}),h('code',p.value)])}});
const AlignControl=defineComponent({props:{label:String,value:String},emits:['update'],setup(p,{emit}){return()=>h('div',{class:'label'},[h('span',p.label),h('div',{class:'segments'},[['left','☰'],['center','≡'],['right','☷']].map(([v,t])=>h('button',{type:'button',class:p.value===v?'selected':'',onClick:()=>emit('update',v)},t)))])}});
</script>

<template>
<AppLayout><Head title="Personalization · Widget editor" />
  <div class="editor-page">
    <header class="editor-header"><div><p class="eyebrow">DECO PERSONALIZATION</p><h1>Widget editor</h1><p>Edit the storefront widget with the same settings structure used by AfterShip Personalization.</p></div><div class="header-actions"><a :href="`/organizations/${organization.id}/stores/${store.id}/personalization`">Back to Personalization</a><button :disabled="!draft||saving||!permissions.manage" @click="save">{{saving?'Saving…':'Save'}}</button></div></header>
    <div v-if="!components.length" class="empty"><h2>No recommendation widget yet</h2><p>Create and publish a strategy placement before editing its storefront appearance.</p></div>
    <div v-else class="editor-shell">
      <aside class="controls">
        <div class="tabs" role="tablist"><button v-for="[value,label] in tabs" :key="value" :class="{active:activeTab===value}" @click="activeTab=value">{{label}}</button></div>
        <div class="control-body">
          <template v-if="activeTab==='settings'">
            <Section title="Widget"><Label text="Widget"><select v-model="selectedId" @change="chooseComponent"><option v-for="row in components" :key="row.uuid" :value="row.uuid">{{row.name}} · {{row.placement}}</option></select></Label><h4>STATUS</h4><Radio label="Enabled" value="enabled" :model="draft?.enabled?'enabled':'disabled'" @update="draft!.enabled=$event==='enabled'"/><Radio label="Disabled" value="disabled" :model="draft?.enabled?'enabled':'disabled'" @update="draft!.enabled=$event==='enabled'"/></Section>
            <Section title="Product recommendations"><p class="help">Select or create a strategy for this widget.</p><Label text="Recommendation strategy"><input :value="draft?.strategy_name" disabled /></Label></Section>
            <Section title="Installation"><p class="help">Copy the theme app block into the selected storefront location, then preview before enabling.</p><button class="secondary" type="button" @click="copyInstallation">Copy code</button></Section>
            <button class="secondary wide" type="button" @click="openExperiment">{{draft?.experiment ? 'Edit A/B test draft' : 'Create A/B test'}}</button>
          </template>
          <template v-else-if="activeTab==='display'">
            <Section title="Widget"><Label text="Border"><select :value="tokens.widget_border" @change="token('widget_border',($event.target as HTMLSelectElement).value)"><option value="none">None</option><option value="solid">Solid</option></select></Label><div class="two"><NumberControl label="MOBILE PADDING · Top/bottom" :value="Number(tokens.mobile_padding_y)" @update="token('mobile_padding_y',$event)"/><NumberControl label="Left/right" :value="Number(tokens.mobile_padding_x)" @update="token('mobile_padding_x',$event)"/><NumberControl label="DESKTOP PADDING · Top/bottom" :value="Number(tokens.desktop_padding_y)" @update="token('desktop_padding_y',$event)"/><NumberControl label="Left/right" :value="Number(tokens.desktop_padding_x)" @update="token('desktop_padding_x',$event)"/></div></Section>
            <Section title="Widget title"><Label text="Title"><input v-model="draft!.heading" maxlength="200" /></Label><NumberControl label="Title padding" :value="Number(tokens.title_padding)" @update="token('title_padding',$event)"/><AlignControl label="Alignment" :value="String(tokens.title_alignment)" @update="token('title_alignment',$event)"/></Section>
            <Section title="Product layout"><div class="two"><NumberControl label="MOBILE · Number of products" :value="draft!.style.mobile_columns" :min="1" :max="3" @update="draft!.style.mobile_columns=$event"/><Label text="Style"><select :value="tokens.mobile_layout" @change="token('mobile_layout',($event.target as HTMLSelectElement).value)"><option value="list">List</option><option value="grid">Grid</option><option value="carousel">Carousel</option></select></Label><NumberControl label="DESKTOP · Number of products" :value="draft!.style.desktop_columns" :min="1" :max="6" @update="draft!.style.desktop_columns=$event"/><Label text="Style"><select v-model="draft!.style.layout"><option value="grid">Grid</option><option value="carousel">Carousel</option></select></Label></div><NumberControl label="Product padding" :value="Number(tokens.product_padding)" @update="token('product_padding',$event)"/></Section>
            <Section title="Product content"><AlignControl label="Content alignment" :value="String(tokens.content_alignment)" @update="token('content_alignment',$event)"/><Check label="Unified alignment" :checked="Boolean(tokens.unified_alignment)" @update="token('unified_alignment',$event)"/><NumberControl label="Content radius" :value="Number(tokens.content_radius)" @update="token('content_radius',$event)"/></Section>
            <Section title="Image"><Label text="Image source"><select :value="tokens.image_source" @change="token('image_source',($event.target as HTMLSelectElement).value)"><option value="product">Product</option><option value="variant">Dynamic variant</option></select></Label><Label text="Image aspect ratio"><select :value="tokens.image_aspect_ratio" @change="token('image_aspect_ratio',($event.target as HTMLSelectElement).value)"><option>1:1</option><option>4:5</option><option>4:3</option></select></Label><Label text="Image border"><select :value="tokens.image_border" @change="token('image_border',($event.target as HTMLSelectElement).value)"><option value="none">None</option><option value="solid">Solid</option></select></Label><NumberControl label="Image radius" :value="Number(tokens.image_radius)" @update="token('image_radius',$event)"/></Section>
            <Section title="PRODUCT INFO"><Check label="Product name" :checked="Boolean(tokens.show_product_name)" @update="token('show_product_name',$event)"/><Check label="Product description" :checked="Boolean(tokens.show_description)" @update="token('show_description',$event)"/><Check label="Product reviews" :checked="false" disabled/><p class="integration">You need to connect a product review app first, such as <a>AfterShip Reviews</a> or <a>Yotpo</a>.<br><a>See all integrations</a> or <a>learn how to connect</a>.</p><Check label="Product price" :checked="draft!.style.show_price" @update="draft!.style.show_price=$event"/><Check label="Compare-at price" :checked="draft!.style.show_compare_at_price" @update="draft!.style.show_compare_at_price=$event"/><Check label="Discount value" :checked="Boolean(tokens.show_discount_value)" @update="token('show_discount_value',$event)"/><Label text="Text"><input :value="tokens.discount_text" @input="token('discount_text',($event.target as HTMLInputElement).value)" /></Label><h4>COMPARISON</h4><Radio label="Use compare-at price" value="compare_at_price" :model="String(tokens.comparison_source)" @update="token('comparison_source',$event)"/><Radio label="Use product price" value="product_price" :model="String(tokens.comparison_source)" @update="token('comparison_source',$event)"/><AlignControl label="Alignment" :value="String(tokens.content_alignment)" @update="token('content_alignment',$event)"/></Section>
            <Section title="VARIANT SELECTOR"><Label text="Display"><select :value="tokens.variant_display" @change="token('variant_display',($event.target as HTMLSelectElement).value)"><option value="dynamic">Dynamic</option><option value="always">Always</option><option value="hidden">Hidden</option></select></Label><Label text="Layout"><select :value="tokens.variant_layout" @change="token('variant_layout',($event.target as HTMLSelectElement).value)"><option value="dropdown">Dropdown</option><option value="buttons">Buttons</option></select></Label><Label text="Preselection"><select :value="tokens.variant_preselection" @change="token('variant_preselection',($event.target as HTMLSelectElement).value)"><option value="smart_match">Smart variant match</option><option value="first_available">First available</option></select></Label><Check label="Show subscription options" :checked="Boolean(tokens.show_subscription_options)" @update="token('show_subscription_options',$event)"/><Check label="Allow customers to change product quantity" :checked="Boolean(tokens.allow_quantity)" @update="token('allow_quantity',$event)"/><NumberControl label="Radius" :value="Number(tokens.selector_radius)" @update="token('selector_radius',$event)"/></Section>
            <Section title="ACTION BUTTONS"><Label text="Select variant button"><input :value="tokens.select_variant_text" maxlength="20" @input="token('select_variant_text',($event.target as HTMLInputElement).value)" /></Label><Label text="Primary button action"><select :value="tokens.primary_action" @change="token('primary_action',($event.target as HTMLSelectElement).value)"><option value="stay">Stay on the same page</option><option value="cart">Go to cart</option><option value="checkout">Go to checkout</option></select></Label><Label text="Primary button text"><input v-model="draft!.button_label" maxlength="20" /></Label><Label text="Success message"><input :value="tokens.success_message" @input="token('success_message',($event.target as HTMLInputElement).value)" /></Label><NumberControl label="Button radius" :value="Number(tokens.button_radius)" @update="token('button_radius',$event)"/></Section>
          </template>
          <template v-else>
            <Section title="Style"><Check label="Auto-sync" :checked="Boolean(tokens.auto_sync_theme)" @update="token('auto_sync_theme',$event)"/><p class="help">The widget section automatically syncs with your Shopify theme. You can adjust colors and fonts below.</p><button class="secondary" type="button" @click="resetTheme">Reset to store theme style</button></Section>
            <Section title="Widget"><ColorControl label="Background" :value="String(tokens.background_color)" @update="token('background_color',$event)"/></Section>
            <Section title="Widget title"><div class="two"><NumberControl label="MOBILE · Font size" :value="Number(tokens.title_font_size_mobile)" :min="12" :max="40" @update="token('title_font_size_mobile',$event)"/><WeightControl label="Font weight" :value="Number(tokens.title_font_weight_mobile)" @update="token('title_font_weight_mobile',$event)"/><NumberControl label="DESKTOP · Font size" :value="Number(tokens.title_font_size_desktop)" :min="12" :max="40" @update="token('title_font_size_desktop',$event)"/><WeightControl label="Font weight" :value="Number(tokens.title_font_weight_desktop)" @update="token('title_font_weight_desktop',$event)"/></div><ColorControl label="MOBILE · Title text" :value="String(tokens.title_color_mobile)" @update="token('title_color_mobile',$event)"/><ColorControl label="DESKTOP · Title text" :value="String(tokens.title_color_desktop)" @update="token('title_color_desktop',$event)"/></Section>
            <Section title="Product info"><NumberControl label="Font size" :value="Number(tokens.product_font_size)" :min="12" :max="40" @update="token('product_font_size',$event)"/><WeightControl label="Font weight" :value="Number(tokens.product_font_weight)" @update="token('product_font_weight',$event)"/><ColorControl label="Product background" :value="String(tokens.product_background_color)" @update="token('product_background_color',$event)"/><ColorControl label="Product name" :value="String(tokens.product_name_color)" @update="token('product_name_color',$event)"/><ColorControl label="Product description" :value="String(tokens.description_color)" @update="token('description_color',$event)"/><ColorControl label="Product price" :value="String(tokens.price_color)" @update="token('price_color',$event)"/><ColorControl label="Compare-at price" :value="String(tokens.compare_at_color)" @update="token('compare_at_color',$event)"/><ColorControl label="Discount value" :value="String(tokens.discount_color)" @update="token('discount_color',$event)"/></Section>
            <Section title="Variant and quantity selectors"><ColorControl label="Selector background" :value="String(tokens.selector_background_color)" @update="token('selector_background_color',$event)"/><ColorControl label="Selector border" :value="String(tokens.selector_border_color)" @update="token('selector_border_color',$event)"/><ColorControl label="Selector text" :value="String(tokens.selector_text_color)" @update="token('selector_text_color',$event)"/></Section>
            <Section title="Action button"><NumberControl label="Font size" :value="Number(tokens.button_font_size)" :min="12" :max="40" @update="token('button_font_size',$event)"/><WeightControl label="Font weight" :value="Number(tokens.button_font_weight)" @update="token('button_font_weight',$event)"/><ColorControl label="Action button background" :value="String(tokens.button_color)" @update="token('button_color',$event)"/><ColorControl label="Action button border" :value="String(tokens.button_border_color)" @update="token('button_border_color',$event)"/><ColorControl label="Action button text" :value="String(tokens.button_text_color)" @update="token('button_text_color',$event)"/></Section>
            <Section title="Custom CSS"><p class="help">Enter style declarations only. They override the settings above.</p><textarea :value="String(tokens.custom_css)" rows="7" @input="token('custom_css',($event.target as HTMLTextAreaElement).value)" /></Section><button class="secondary wide" type="button" @click="openExperiment">{{draft?.experiment ? 'Edit A/B test draft' : 'Create A/B test'}}</button>
          </template>
        </div>
      </aside>
      <main class="preview"><div class="preview-toolbar"><strong>Live preview</strong><div class="device-switch"><button type="button" :class="{selected:previewDevice==='desktop'}" @click="previewDevice='desktop'">Desktop</button><button type="button" :class="{selected:previewDevice==='mobile'}" @click="previewDevice='mobile'">Mobile</button></div></div><div class="canvas" :class="previewDevice"><section v-if="draft" class="widget" :style="previewStyle"><h2 :style="{paddingBottom:`${tokens.title_padding}px`,textAlign:String(tokens.title_alignment) as any,color:String(tokens[previewDevice==='mobile'?'title_color_mobile':'title_color_desktop']),fontSize:`${tokens[previewDevice==='mobile'?'title_font_size_mobile':'title_font_size_desktop']}px`,fontWeight:String(tokens[previewDevice==='mobile'?'title_font_weight_mobile':'title_font_weight_desktop'])}">{{draft.heading}}</h2><div :style="previewGrid"><article v-for="product in previewProducts" :key="product.shopify_product_id" class="product" :style="{padding:`${tokens.product_padding}px`,borderRadius:`${tokens.content_radius}px`,background:String(tokens.product_background_color)}"><div v-if="draft.style.show_image" class="image" :style="{borderRadius:`${tokens.image_radius}px`,aspectRatio:String(tokens.image_aspect_ratio).replace(':',' / ')}"><img v-if="product.image_url" :src="product.image_url" :alt="product.title"><span v-else>Product image</span></div><p v-if="draft.style.show_vendor" class="vendor">{{product.vendor}}</p><h3 v-if="tokens.show_product_name" :style="{color:String(tokens.product_name_color),fontSize:`${tokens.product_font_size}px`,fontWeight:String(tokens.product_font_weight)}">{{product.title}}</h3><p v-if="tokens.show_description" :style="{color:String(tokens.description_color)}">A short product description appears here.</p><p v-if="draft.style.show_price" class="price" :style="{color:String(tokens.price_color)}">{{money(product.price,product.currency)}} <s v-if="draft.style.show_compare_at_price&&product.compare_at_price" :style="{color:String(tokens.compare_at_color)}">{{money(product.compare_at_price,product.currency)}}</s></p><p v-if="tokens.show_discount_value&&discount(product)" :style="{color:String(tokens.discount_color)}">{{String(tokens.discount_text).replace('*|DISCOUNT|*',discount(product)!)}}</p><select v-if="tokens.variant_display!=='hidden'" class="variant"><option>Default variant</option></select><div v-if="tokens.allow_quantity" class="qty">− <span>1</span> +</div><button v-if="draft.style.show_add_to_cart" :style="{borderRadius:`${tokens.button_radius}px`,background:String(tokens.button_color),color:String(tokens.button_text_color),fontSize:`${tokens.button_font_size}px`,fontWeight:String(tokens.button_font_weight)}">{{draft.button_label}}</button></article></div></section></div></main>
    </div>
    <div v-if="experimentOpen" class="modal-backdrop" @click.self="experimentOpen=false"><form class="modal" @submit.prevent="createExperiment"><header><div><p class="eyebrow">A/B TEST</p><h2>Create design experiment</h2></div><button type="button" class="close" @click="experimentOpen=false">×</button></header><p class="help">Variant A uses the current saved design. Configure the draft for Variant B; the experiment remains a draft until an experiment runner is enabled.</p><Label text="Experiment name"><input v-model="experimentForm.name" maxlength="80" required /></Label><Label text="Variant B name"><input v-model="experimentForm.variant_name" maxlength="80" required /></Label><Label text="Primary metric"><select v-model="experimentForm.primary_metric"><option value="revenue">Revenue</option><option value="conversion_rate">Conversion rate</option><option value="average_order_value">Average order value</option></select></Label><NumberControl label="Variant B traffic" :value="experimentForm.variant_traffic_percentage" :min="1" :max="99" @update="experimentForm.variant_traffic_percentage=$event"/><div class="traffic"><span>Variant A · {{100-experimentForm.variant_traffic_percentage}}%</span><span>Variant B · {{experimentForm.variant_traffic_percentage}}%</span></div><footer><button type="button" class="secondary" @click="experimentOpen=false">Cancel</button><button type="submit" class="primary">Save draft</button></footer></form></div>
    <p v-if="message" class="message">{{message}}</p>
  </div>
</AppLayout>
